describe('Mark Record as Favourite', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.login('testuser@example.com', 'password123');
    cy.get('[data-testid="records-list"]').should('be.visible');
  });

  it('should mark a record as favourite successfully', () => {
    cy.get('[data-testid="record-item"]').first().within(() => {
      cy.get('[data-testid="favourite-button"]')
        .should('not.have.class', 'active')
        .click();

      cy.get('[data-testid="favourite-button"]')
        .should('have.class', 'active')
        .should('have.attr', 'aria-pressed', 'true');
    });

    cy.get('[data-testid="success-toast"]')
      .should('be.visible')
      .should('contain', 'Record marked as favourite');
  });

  it('should unmark a record from favourite', () => {
    cy.get('[data-testid="record-item"]').first().within(() => {
      cy.get('[data-testid="favourite-button"]').click();
      cy.get('[data-testid="favourite-button"]').should('have.class', 'active');
    });

    cy.get('[data-testid="record-item"]').first().within(() => {
      cy.get('[data-testid="favourite-button"]').click();
      cy.get('[data-testid="favourite-button"]').should('not.have.class', 'active');
    });

    cy.get('[data-testid="success-toast"]')
      .should('be.visible')
      .should('contain', 'Record removed from favourites');
  });

  it('should persist favourite status after page reload', () => {
    cy.get('[data-testid="record-item"]').first().within(() => {
      cy.get('[data-testid="favourite-button"]').click();
      cy.get('[data-testid="favourite-button"]').should('have.class', 'active');
    });

    cy.reload();
    cy.get('[data-testid="records-list"]').should('be.visible');

    cy.get('[data-testid="record-item"]').first().within(() => {
      cy.get('[data-testid="favourite-button"]').should('have.class', 'active');
    });
  });

  it('should handle favourite action on non-existent record gracefully', () => {
    cy.intercept('PATCH', '**/api/records/*/favourite', {
      statusCode: 404,
      body: { error: 'Record not found' }
    }).as('favouriteRequest');

    cy.get('[data-testid="record-item"]').first().within(() => {
      cy.get('[data-testid="favourite-button"]').click();
    });

    cy.wait('@favouriteRequest');
    cy.get('[data-testid="error-toast"]')
      .should('be.visible')
      .should('contain', 'Unable to mark as favourite');
  });
});
